import React from 'react';
import { motion } from 'framer-motion';
import { PlusCircle, ClipboardList, Receipt } from 'lucide-react';

const TABS = [
  { key: 'new', label: 'Nuevo Pedido', icon: PlusCircle },
  { key: 'orders', label: 'Pedidos por Cobrar', icon: ClipboardList },
  { key: 'invoices', label: 'Facturas Emitidas', icon: Receipt },
];

/**
 * Selector de pestañas con una "píldora" que se desliza entre opciones
 * (framer-motion layoutId), en vez de simplemente cambiar el color de fondo.
 */
const TabSwitcher = ({ active, onChange, pendingCount = 0 }) => (
  <div className="cashier-tabs" role="tablist">
    {TABS.map((tab) => {
      const Icon = tab.icon;
      const isActive = active === tab.key;
      return (
        <button
          key={tab.key}
          type="button"
          role="tab"
          aria-selected={isActive}
          className={`cashier-tab ${isActive ? 'active' : ''}`}
          onClick={() => onChange(tab.key)}
        >
          {isActive && (
            <motion.span
              layoutId="cashier-tab-pill"
              className="cashier-tab-pill"
              transition={{ type: 'spring', stiffness: 420, damping: 34 }}
            />
          )}
          <span className="cashier-tab-content">
            <Icon size={16} strokeWidth={2} />
            {tab.label}
            {tab.key === 'orders' && pendingCount > 0 && (
              <span className="cashier-tab-count">{pendingCount}</span>
            )}
          </span>
        </button>
      );
    })}
  </div>
);

export default TabSwitcher;
